use std::io::{Cursor,Read,Write};
use rhwp::{DocumentCore,model::{control::Control,paragraph::{Paragraph,CharShapeRef},table::{Table,Cell}},serializer::serialize_hwp_with_report};
use sha2::{Digest,Sha256};use serde_json::json;
fn sha(b:&[u8])->String{Sha256::digest(b).iter().map(|x|format!("{x:02x}")).collect()}
fn para(text:&str)->Paragraph{Paragraph{text:text.into(),char_count:text.encode_utf16().count() as u32+1,char_shapes:vec![CharShapeRef{start_pos:0,char_shape_id:0}],char_offsets:(0..text.encode_utf16().count() as u32).collect(),..Default::default()}}
fn read(c:&mut cfb::CompoundFile<Cursor<Vec<u8>>>,path:&str)->Vec<u8>{let mut b=vec![];c.open_stream(path).unwrap().read_to_end(&mut b).unwrap();b}
#[test]fn make_parseable_owned_unknown_bytes(){
let out=std::path::PathBuf::from(std::env::var("JUEONY_UNKNOWN_BYTES_OUT").unwrap());std::fs::create_dir_all(&out).unwrap();
let mut c=DocumentCore::new_empty();c.create_blank_document_native().unwrap();let mut d=c.document().clone();d.sections[0].raw_stream=None;
let mut t=Table{row_count:1,col_count:1,row_sizes:vec![1],cells:vec![Cell{paragraphs:vec![para("OWN SYNTHETIC CELL")],width:14000,height:2000,col_span:1,row_span:1,..Default::default()}],..Default::default()};t.common.width=14000;t.common.height=2000;t.rebuild_grid();let mut root=para("OWN UNKNOWN CONTROL BYTE FIXTURE");root.controls.push(Control::Table(Box::new(t)));root.char_count+=8;for x in &mut root.char_offsets{*x+=8;}d.sections[0].paragraphs[0]=root;
let known=serialize_hwp_with_report(&d).unwrap();assert!(known.content_loss().is_empty());let known=known.bytes().to_vec();let parsed=DocumentCore::from_bytes(&known).unwrap();let known_controls=&parsed.document().sections[0].paragraphs[0].controls;let table_index=known_controls.iter().position(|x|matches!(x,Control::Table(_))).expect("generated known table");assert_eq!(known_controls.iter().filter(|x|matches!(x,Control::Table(_))).count(),1);
let mut compound=cfb::CompoundFile::open(Cursor::new(known.clone())).unwrap();let header=read(&mut compound,"/FileHeader");let compressed=u32::from_le_bytes(header[36..40].try_into().unwrap())&1!=0;let stream=read(&mut compound,"/BodyText/Section0");let raw=if compressed{let mut v=vec![];flate2::read::DeflateDecoder::new(stream.as_slice()).read_to_end(&mut v).unwrap();v}else{stream.clone()};let mut changed=raw.clone();let mut pos=0;let mut changes=vec![];
while pos<raw.len(){assert!(pos+4<=raw.len());let header=u32::from_le_bytes(raw[pos..pos+4].try_into().unwrap());let tag=header&1023;let level=(header>>10)&1023;let mut size=(header>>20) as usize;let record=pos;pos+=4;if size==4095{size=u32::from_le_bytes(raw[pos..pos+4].try_into().unwrap())as usize;pos+=4;}assert!(pos+size<=raw.len());if tag==71&&size>=4&&raw[pos..pos+4]==u32::from_be_bytes(*b"tbl ").to_le_bytes(){changed[pos..pos+4].copy_from_slice(&0x11223344u32.to_le_bytes());changes.push(json!({"recordOffset":record,"payloadOffset":pos,"tag":tag,"level":level,"payloadBytes":size,"changedBytes":4,"before4ccLe":raw[pos..pos+4],"after4ccLe":changed[pos..pos+4]}));}pos+=size;}
assert_eq!(changes.len(),1);let diffs=raw.iter().zip(&changed).enumerate().filter(|(_, (a,b))|a!=b).map(|(i,_)|i).collect::<Vec<_>>();let offset=changes[0]["payloadOffset"].as_u64().unwrap()as usize;assert_eq!(diffs,(offset..offset+4).collect::<Vec<_>>());
let packed=if compressed{let mut e=flate2::write::DeflateEncoder::new(vec![],flate2::Compression::default());e.write_all(&changed).unwrap();e.finish().unwrap()}else{changed};compound.create_stream("/BodyText/Section0").unwrap().write_all(&packed).unwrap();let mutated=compound.into_inner().into_inner();let mut a=cfb::CompoundFile::open(Cursor::new(known.clone())).unwrap();let mut b=cfb::CompoundFile::open(Cursor::new(mutated.clone())).unwrap();let paths=a.walk().filter(|x|x.is_stream()).map(|x|x.path().to_string_lossy().to_string()).collect::<Vec<_>>();for path in &paths{if path!="/BodyText/Section0"{assert_eq!(read(&mut a,path),read(&mut b,path),"other stream changed: {path}");}}
let reopened=DocumentCore::from_bytes(&mutated).unwrap();let controls=&reopened.document().sections[0].paragraphs[0].controls;assert_eq!(controls.iter().filter(|x|matches!(x,Control::Unknown(u)if u.ctrl_id==0x11223344)).count(),1);assert_eq!(controls.len(),known_controls.len());let model=format!("{:?}",reopened.document());let report=reopened.export_hwpx_native_with_report().unwrap();assert_eq!(report.content_loss().len(),1);assert_eq!(report.content_loss().losses()[0].path,format!("section/0/body/paragraph/0/control/{table_index}"));assert_eq!(format!("{:?}",reopened.document()),model);
std::fs::write(out.join("known-own-table.hwp"),&known).unwrap();std::fs::write(out.join("unknown-own-table.hwp"),&mutated).unwrap();std::fs::write(out.join("result.json"),serde_json::to_vec_pretty(&json!({"knownSha256":sha(&known),"unknownSha256":sha(&mutated),"ownSyntheticOnly":true,"sourceCompressed":compressed,"recordChanges":changes,"otherStreamsUnchanged":true,"parsedUnknownCount":1,"sourceModelUnchanged":true,"knownBytes":known.len(),"unknownBytes":mutated.len(),"report":serde_json::from_str::<serde_json::Value>(&report.content_loss().to_json()).unwrap()})).unwrap()).unwrap();}
